import heapq
from typing import List

class Solution:
    def getSkyline(self, buildings: List[List[int]]) -> List[List[int]]:
        events = []
        for L, R, H in buildings:
            events.append((L, -H, R))
            events.append((R, 0, 0))
        events.sort()

        res = [[0, 0]]
        heap = [(0, float("inf"))]

        for x, neg_h, r in events:
            if neg_h != 0:
                heapq.heappush(heap, (neg_h, r))
            while heap[0][1] <= x:
                heapq.heappop(heap)
            max_h = -heap[0][0]
            if res[-1][1] != max_h:
                res.append([x, max_h])

        return res[1:]

class Solution {
public:
    vector<vector<int>> getSkyline(vector<vector<int>>& buildings) {
        vector<tuple<int, int, int>> events;
        for (const auto& b : buildings) {
            events.emplace_back(b[0], -b[2], b[1]);
            events.emplace_back(b[1], 0, 0);
        }
        sort(events.begin(), events.end());
        priority_queue<pair<int, int>> pq; // (height, right)
        pq.push({0, INT_MAX});
        vector<vector<int>> res;
        int prev_h = 0;
        for (const auto& [x, neg_h, r] : events) {
            if (neg_h != 0) {
                pq.push({-neg_h, r});
            }
            while (pq.top().second <= x) {
                pq.pop();
            }
            int curr_h = pq.top().first;
            if (curr_h != prev_h) {
                res.push_back({x, curr_h});
                prev_h = curr_h;
            }
        }
        return res;
    }
};

class Solution {
    public List<List<Integer>> getSkyline(int[][] buildings) {
        List<int[]> events = new ArrayList<>();
        for (int[] b : buildings) {
            events.add(new int[]{b[0], -b[2], b[1]});
            events.add(new int[]{b[1], 0, 0});
        }
        events.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        java.util.PriorityQueue<int[]> pq = new java.util.PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));
        pq.offer(new int[]{0, Integer.MAX_VALUE});
        List<List<Integer>> res = new ArrayList<>();
        int prevH = 0;
        for (int[] ev : events) {
            int x = ev[0], negH = ev[1], r = ev[2];
            if (negH != 0) pq.offer(new int[]{-negH, r});
            while (pq.peek()[1] <= x) pq.poll();
            int currH = pq.peek()[0];
            if (currH != prevH) {
                res.add(java.util.Arrays.asList(x, currH));
                prevH = currH;
            }
        }
        return res;
    }
}

/**
 * @param {number[][]} buildings
 * @return {number[][]}
 */
var getSkyline = function(buildings) {
    const events = [];
    for (const [L, R, H] of buildings) {
        events.push([L, -H, R]);
        events.push([R, 0, 0]);
    }
    events.sort((a, b) => a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]);
    const heap = [[0, Infinity]];
    const push = (item) => {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) {
            const p = Math.floor((i - 1) / 2);
            if (heap[p][0] >= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let best = i;
                const l = 2 * i + 1, r = 2 * i + 2;
                if (l < heap.length && heap[l][0] > heap[best][0]) best = l;
                if (r < heap.length && heap[r][0] > heap[best][0]) best = r;
                if (best === i) break;
                [heap[i], heap[best]] = [heap[best], heap[i]];
                i = best;
            }
        }
        return top;
    };
    const res = [];
    let prevH = 0;
    for (const [x, negH, r] of events) {
        if (negH !== 0) push([-negH, r]);
        while (heap[0][1] <= x) pop();
        const currH = heap[0][0];
        if (currH !== prevH) {
            res.push([x, currH]);
            prevH = currH;
        }
    }
    return res;
};
